import React, { useState } from 'react';
import PropTypes from 'prop-types';
import Tabs, { tabsClasses } from '@mui/material/Tabs';
import Tab from '@mui/material/Tab';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import "../styles/studenthome.css";
import StdHead from '../components/StdHead';
import ProfileTab from '../components/ProfileTab';
import AttendanceTab from '../components/AttendanceTab';
import MarksTab from '../components/MarksTab';
import AssignmentsTab from '../components/AssignmentsTab';
import CoursesTab from '../components/CoursesTab';
import ScheduleTab from '../components/ScheduleTab';
import NotificationsTab from '../components/NotificationsTab';

// Import MUI Icons
import EventNoteIcon from '@mui/icons-material/EventNote';
import GradeIcon from '@mui/icons-material/Grade';
import AssignmentIcon from '@mui/icons-material/Assignment';
import ScheduleIcon from '@mui/icons-material/Schedule';
import LibraryBooksIcon from '@mui/icons-material/LibraryBooks';
import NotificationsIcon from '@mui/icons-material/Notifications';
import AccountCircleIcon from '@mui/icons-material/AccountCircle';

// Import Charts
import { PieChart, Pie, Cell, Tooltip, Legend } from 'recharts';

// Sample Data for Pie Chart (Attendance)
const attendanceData = [
  { name: "Present", value: 80, color: "#4caf50" },
  { name: "Absent", value: 20, color: "#f44336" }
];

const tabsData = [
  { 
    label: "Profile", 
    icon: <AccountCircleIcon />, 
    content: (
      <Box className="profileContent">


<ProfileTab />

      </Box>
    ) 
  },
  { 
    label: "Attendance", 
    icon: <EventNoteIcon />, 
    content: (
      <Box className="attendanceContent">
        
<AttendanceTab />

      </Box>
    ) 
  },
  { 
    label: "Marks", 
    icon: <GradeIcon />, 
    content: (
      <Box className="marksContent">
        
<MarksTab />  

      </Box>
    ) 
  },
  { 
    label: "Assignments", 
    icon: <AssignmentIcon />, 
    content: (
      <Box className="assignmentsContent">
       
<AssignmentsTab />

      </Box>
    ) 
  },
  { 
    label: "Schedule", 
    icon: <ScheduleIcon />, 
    content: (
      <Box className="scheduleContent">
        <ScheduleTab /> 
      </Box>
    ) 
  },
  { 
    label: "Courses", 
    icon: <LibraryBooksIcon />, 
    content: (
      <Box className="coursesContent">
      
      <CoursesTab />
      </Box>
    ) 
  },
  { 
    label: "Notifications", 
    icon: <NotificationsIcon />, 
    content: (
      <Box className="notificationsContent">
        <NotificationsTab />
      </Box>
    ) 
  }
];

function TabPanel({ children, value, index }) {
  return (
    <div role="tabpanel" hidden={value !== index} id={`tabpanel-${index}`} aria-labelledby={`tab-${index}`}>
      {value === index && (
        <Box className="tabContent">
          {children}
        </Box>
      )}
    </div>
  );
}

TabPanel.propTypes = {
  children: PropTypes.node,
  index: PropTypes.number.isRequired,
  value: PropTypes.number.isRequired,
};

export default function StudentHome() {
  const [value, setValue] = useState(0);
  const handleChange = (event, newValue) => setValue(newValue);

  return (
    <div className="studentmain">
      <div className="stdtop">
        <div className='hlogo'><div className='hpics'></div></div>
        <StdHead />
      </div>

      <Box className="tabContainer">
        <Tabs
          orientation="vertical"
          variant="scrollable"
          value={value}
          onChange={handleChange}
          className="tabs desktopTabs"
        >
          {tabsData.map((tab, i) => (
            <Tab key={i} icon={tab.icon} label={tab.label} />
          ))}
        </Tabs>
        <div className="tabPanels">
          {tabsData.map((tab, i) => (
            <TabPanel key={i} value={value} index={i}>
              {tab.content}
            </TabPanel>
          ))}
        </div>
      </Box>

      <Box className="mobileTabs">
        <Tabs value={value} onChange={handleChange} variant="scrollable">
          {tabsData.map((tab, i) => (
            <Tab key={i} icon={tab.icon} label={tab.label} />
          ))}
        </Tabs>
      </Box>

      <div className="tabPanels mobilePanels">
        {tabsData.map((tab, i) => (
          <TabPanel key={i} value={value} index={i}>
            {tab.content}
          </TabPanel>
        ))}
      </div>
    </div>
  );
}
