import React from 'react';
import "../styles/land.css";
import Button from '@mui/material/Button';
import AccountCircle from '@mui/icons-material/AccountCircle';
import Stack from '@mui/material/Stack';
import { useState, useEffect } from "react";
import { Link } from 'react-router-dom';

function TypingAnimation() {
  const text = "Welcome to Academia Login";
  const [displayText, setDisplayText] = useState("");
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (index < text.length) {
      const timeout = setTimeout(() => {
        setDisplayText((prev) => prev + text[index]);
        setIndex(index + 1);
      }, 100);
      return () => clearTimeout(timeout);
    }
  }, [index, text]);

  return <span className="typing-text">{displayText}</span>;
}

function Land() {
  return (
    <div className="landmain">
      <div className='landleft'>
        <div className="vvvv">
          <TypingAnimation />
        </div>
      </div>
      <div className='landright'>
        <div className='landlogo'>
          <div className='llll'></div>
        </div>
        <div className='landb1'>
          <Stack direction="row" spacing={2}>
          <Link to="/StudentLogin"> <Button  
              className="b"
              variant="outlined"
              startIcon={<AccountCircle style={{ fontSize: 40, marginRight: '20px', color: 'black' }} />}
              sx={{
                color: 'black',
                borderColor: 'black',
                '&:hover': {
                  borderColor: 'black',
                  backgroundColor: 'rgba(114, 112, 112, 0.21)',
                },
              }}
            >
              Student
            </Button>

</Link> 

          </Stack>
        </div>
        <div className='landb2'>
          <Stack direction="row" spacing={2}>
           <Link to="/StaffLogin"> 
            <Button
              className="b"
              variant="outlined"
              startIcon={<AccountCircle style={{ fontSize: 40, marginRight: '40px', color: 'black' }} />}
              sx={{
                color: 'black',
                borderColor: 'black',
                '&:hover': {
                  borderColor: 'black',
                   backgroundColor: 'rgba(114, 112, 112, 0.21)',
                },
              }}
            >
              Staff
            </Button></Link>
          </Stack>
        </div>
      </div>
    </div>
  );
}

export default Land;

