import React, { useState } from "react";
import { Box, Typography, List, ListItem, ListItemText, Badge, Divider } from "@mui/material";
import "../styles/notification.css";

const NotificationsTab = () => {
  // Sample notifications data
  const [notifications, setNotifications] = useState([
    { title: "Assignment 1 Deadline", detail: "Submit by 10th March", isNew: true },
    { title: "Marks Uploaded", detail: "Math Internal 1 marks are available", isNew: false },
    { title: "Physics Project", detail: "Complete project by 20th March", isNew: true },
    { title: "New Class Schedule", detail: "Updated schedule from next week", isNew: false },
  ]);

  return (
    <Box className="notificationsContent">
      <Typography variant="h5" sx={{ marginBottom: "20px", color: "#b71c1c" }}>
        Latest Notifications
      </Typography>
      <List>
        {notifications.map((notification, index) => (
          <React.Fragment key={index}>
            <ListItem sx={{ display: "flex", alignItems: "center" }}>
              <Badge
                color="primary"
                variant="dot"
                invisible={!notification.isNew}
                sx={{ marginRight: "10px" }}
              />
              <ListItemText
                primary={notification.title}
                secondary={notification.detail}
                primaryTypographyProps={{ fontWeight: notification.isNew ? "bold" : "normal" }}
              />
            </ListItem>
            <Divider />
          </React.Fragment>
        ))}
      </List>
    </Box>
  );
};

export default NotificationsTab;
