import React, { useState } from "react";
import { Box, Typography, Button, TextField, List, ListItem, ListItemText } from "@mui/material";
import "../styles/assignment.css";

const AssignmentsTab = () => {
  const [assignments, setAssignments] = useState([]);
  const [file, setFile] = useState(null);

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = () => {
    if (file) {
      setAssignments((prevAssignments) => [
        ...prevAssignments,
        { name: file.name, date: new Date().toLocaleString() },
      ]);
      setFile(null);
    } else {
      alert("Please select a file before submitting!");
    }
  };

  return (
    <Box className="assignmentsContent">
      <Typography variant="h5" sx={{ marginBottom: "20px", color: "#ff6f00" }}>
        Assignments Management
      </Typography>
      <Box className="uploadSection">
        <Typography variant="h6" sx={{ marginBottom: "10px" }}>
          Upload Assignment
        </Typography>
        <TextField
          type="file"
          inputProps={{ accept: ".pdf,.docx,.pptx,.txt" }}
          onChange={handleFileChange}
          sx={{ marginBottom: "10px" }}
        />
        <Button
          variant="contained"
          color="primary"
          onClick={handleSubmit}
          disabled={!file}
          sx={{ width: "150px" }}
        >
          Submit
        </Button>
      </Box>
      <Box className="listSection" sx={{ marginTop: "30px" }}>
        <Typography variant="h6" sx={{ marginBottom: "10px" }}>
          Submitted Assignments
        </Typography>
        {assignments.length === 0 ? (
          <Typography>No assignments uploaded yet!</Typography>
        ) : (
          <List>
            {assignments.map((assignment, index) => (
              <ListItem key={index}>
                <ListItemText
                  primary={assignment.name}
                  secondary={`Uploaded on: ${assignment.date}`}
                />
              </ListItem>
            ))}
          </List>
        )}
      </Box>
    </Box>
  );
};

export default AssignmentsTab;

