import React, { useState } from "react";
import { Box, Tabs, Tab, Typography, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper } from "@mui/material";
import { BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, ResponsiveContainer } from "recharts";

const MarksTab = () => {
  const [selectedInternal, setSelectedInternal] = useState(0);

  const marksData = [
    {
      internal: "Internal 1",
      data: [
        { subject: "Math", marks: 85 },
        { subject: "Science", marks: 90 },
        { subject: "History", marks: 75 },
        { subject: "English", marks: 70 },
        { subject: "Physics", marks: 60 },
      ],
    },
    {
      internal: "Internal 2",
      data: [
        { subject: "Math", marks: 88 },
        { subject: "Science", marks: 92 },
        { subject: "History", marks: 78 },
        { subject: "English", marks: 65 },
        { subject: "Physics", marks: 58 },
      ],
    },
    {
      internal: "Internal 3",
      data: [
        { subject: "Math", marks: 90 },
        { subject: "Science", marks: 95 },
        { subject: "History", marks: 80 },
        { subject: "English", marks: 72 },
        { subject: "Physics", marks: 55 },
      ],
    },
  ];

  const handleInternalChange = (event, newValue) => {
    setSelectedInternal(newValue);
  };

  const currentData = marksData[selectedInternal].data;
  const totalMarks = currentData.reduce((sum, item) => sum + item.marks, 0);

  return (
    <Box className="marksContent">
      {/* Tabs for Internals */}
      <Tabs
        value={selectedInternal}
        onChange={handleInternalChange}
        centered
        textColor="primary"
        indicatorColor="primary"
      >
        <Tab label="Internal 1" />
        <Tab label="Internal 2" />
        <Tab label="Internal 3" />
      </Tabs>

      {/* Bar Graph */}
      <Box sx={{ padding: "20px" }}>
        <Typography variant="h6">
          {marksData[selectedInternal].internal} - Subject-wise Marks
        </Typography>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={currentData}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="subject" />
            <YAxis />
            <Tooltip />
            <Bar dataKey="marks" fill="#007bff" />
          </BarChart>
        </ResponsiveContainer>
      </Box>

      {/* Marks List View */}
      <Box sx={{ padding: "20px", width: "90%" }}>
        <Typography variant="h6">Marks Overview</Typography>
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell><strong>Subject</strong></TableCell>
                <TableCell align="right"><strong>Marks</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {currentData.map((item, index) => (
                <TableRow key={index}>
                  <TableCell>{item.subject}</TableCell>
                  <TableCell
                    align="right"
                    sx={{
                      color: item.marks < 40 ? "red" : "inherit", // Mark low scores in red
                      fontWeight: item.marks < 40 ? "bold" : "normal",
                    }}
                  >
                    {item.marks}
                  </TableCell>
                </TableRow>
              ))}
              <TableRow>
                <TableCell><strong>Total Marks</strong></TableCell>
                <TableCell align="right"><strong>{totalMarks}</strong></TableCell>
              </TableRow>
            </TableBody>
          </Table>
        </TableContainer>
      </Box>
    </Box>
  );
};

export default MarksTab;
