import React, { useState } from "react";
import { Box, Typography, MenuItem, Select, FormControl, InputLabel, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, TextField } from "@mui/material";
import "../styles/schedule.css";

const ScheduleTab = () => {
  const days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];
  const [selectedDay, setSelectedDay] = useState("Monday");
  const [selectedDate, setSelectedDate] = useState("");

  const schedule = {
    Monday: [
      { time: "9:00 AM - 9:40 AM", subject: "Math" },
      { time: "9:50 AM - 10:30 AM", subject: "Science" },
      { time: "10:30 AM - 10:40 AM", subject: "Morning Break", breakType: "red" },

      { time: "10:40 AM - 11:20 AM", subject: "History" },
      { time: "11:30 AM - 12:10 PM", subject: "Geography" },
      { time: "12:10 PM - 12:50 PM", subject: "English" },
      { time: "12:50 PM - 1:30 PM", subject: "Lunch Break", breakType: "green" },
      { time: "1:30 PM - 2:10 PM", subject: "Physics" },
      { time: "2:20 PM - 3:00 PM", subject: "Chemistry" },
      { time: "3:00 PM - 3:10 PM", subject: "Evening Break", breakType: "red" },
      { time: "3:10 PM - 3:50 PM", subject: "Physical Education" },
    ],
    // Add other days similarly...
  };

  const handleDayChange = (event) => {
    setSelectedDay(event.target.value);
  };

  const handleDateChange = (event) => {
    setSelectedDate(event.target.value);
  };

  return (
    <Box className="scheduleContent">
      <Typography variant="h5" sx={{ marginBottom: "20px", color: "black" }}>
        Class Schedule
      </Typography>
      <Box className="selectors" sx={{ display: "flex", justifyContent: "center", gap: "20px", marginBottom: "20px" }}>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel>Day</InputLabel>
          <Select value={selectedDay} onChange={handleDayChange}>
            {days.map((day) => (
              <MenuItem key={day} value={day}>
                {day}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        <TextField
          type="date"
          value={selectedDate}
          onChange={handleDateChange}
          sx={{ width: "200px" }}
        />
      </Box>
      <TableContainer component={Paper} sx={{ maxWidth: 800 }}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell><strong>Time</strong></TableCell>
              <TableCell><strong>Subject</strong></TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {schedule[selectedDay]?.map((slot, index) => (
              <TableRow key={index} className={slot.breakType ? slot.breakType : ""}>
                <TableCell>{slot.time}</TableCell>
                <TableCell>{slot.subject}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default ScheduleTab;
