import React from "react";
import { Box, Typography, Grid, Paper } from "@mui/material";
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from "recharts";
import "../styles/attendance.css";

const attendanceData = [
  { name: "Present", value: 80, color: "url(#presentGradient)" },
  { name: "Absent", value: 20, color: "url(#absentGradient)" },
];

const monthlyAttendance = {
  January: { present: 20, absent: 5 },
  February: { present: 18, absent: 7 },
  March: { present: 22, absent: 3 },
};

const AttendanceTab = () => {
  const totalPresent = attendanceData[0].value;
  const totalAbsent = attendanceData[1].value;
  const totalPercentage = ((totalPresent / (totalPresent + totalAbsent)) * 100).toFixed(2);

  return (
    <Box className="attendanceContent">
      <Typography variant="h5" className="header">
        Attendance Overview
      </Typography>

      {/* Doughnut Chart Section */}
      <Box className="chartSection">
        <ResponsiveContainer width="100%" height={300}>
          <PieChart>
            {/* Gradient Definitions */}
            <defs>
              <linearGradient id="presentGradient" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stopColor="#4caf50" />
                <stop offset="100%" stopColor="#81c784" />
              </linearGradient>
              <linearGradient id="absentGradient" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stopColor="#f44336" />
                <stop offset="100%" stopColor="#ef9a9a" />
              </linearGradient>
            </defs>

            {/* Doughnut Chart */}
            <Pie
              data={attendanceData}
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={90}
              dataKey="value"
              label={({ name, percent }) => `${name} (${(percent * 100).toFixed(0)}%)`}
            >
              {attendanceData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            <Tooltip />
            <Legend />
          </PieChart>
        </ResponsiveContainer>
        <Typography variant="h6" className="percentage">
          Total Attendance: {totalPercentage}%
        </Typography>
      </Box>

      {/* Attendance Summary Section */}
      <Box className="summarySection">
        <Paper className="summaryCard">
          <Typography variant="body1" className="alignedText">
            <strong>Total Present Days:</strong> {totalPresent} days
          </Typography>
          <Typography variant="body1" className="alignedText">
            <strong>Total Absent Days:</strong> {totalAbsent} days
          </Typography>
          <Typography variant="body1" className="alignedText">
            <strong>Total Percentage:</strong> {totalPercentage}%
          </Typography>
        </Paper>

        <Typography variant="h6" className="monthlyHeader">
          Monthly Breakdown
        </Typography>
        <Grid container spacing={2}>
          {Object.entries(monthlyAttendance).map(([month, data], index) => (
            <Grid item xs={12} sm={6} md={4} key={index}>
              <Paper className="monthCard">
                <Typography variant="h6">{month}</Typography>
                <Typography variant="body2">Present: {data.present} days</Typography>
                <Typography variant="body2">Absent: {data.absent} days</Typography>
              </Paper>
            </Grid>
          ))}
        </Grid>
      </Box>
    </Box>
  );
};

export default AttendanceTab;
