import React from 'react';
import "../styles/profiletab.css";

const ProfileTab = () => {
  const student = {
    name: "John Doe",
    email: "johndoe@example.com",
    localGuardian: {
      name: "Jane Doe",
      phone: "+91 9876543210",
    },
    bloodGroup: "O+",
    age: 20,
  };

  return (
    <div className='profilemain'>
      <div className='profilecard'>
        <h1>Student Profile</h1>
        <div className='profiledetails'>
          <div className='profile-row'>
            <span className='label'>Name:</span>
            <span className='value'>{student.name}</span>
          </div>
          <div className='profile-row'>
            <span className='label'>Email:</span>
            <span className='value'>{student.email}</span>
          </div>
          <div className='profile-row'>
            <span className='label'>Local Guardian:</span>
            <span className='value'>{student.localGuardian.name}</span>
          </div>
          <div className='profile-row'>
            <span className='label'>Guardian's Phone:</span>
            <span className='value'>{student.localGuardian.phone}</span>
          </div>
          <div className='profile-row'>
            <span className='label'>Blood Group:</span>
            <span className='value'>{student.bloodGroup}</span>
          </div>
          <div className='profile-row'>
            <span className='label'>Age:</span>
            <span className='value'>{student.age}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProfileTab;
