import React from "react";
import { Box, Typography, Grid, Card, CardContent } from "@mui/material";
import "../styles/courses.css";

const CoursesTab = () => {
  const courses = [
    { name: "Mathematics", code: "MATH101", instructor: "Dr. John Doe", schedule: "Mon & Wed, 9:00-10:30 AM" },
    { name: "Physics", code: "PHYS202", instructor: "Prof. Jane Smith", schedule: "Tue & Thu, 11:00-12:30 PM" },
    { name: "History", code: "HIST303", instructor: "Dr. Alan White", schedule: "Fri, 2:00-4:00 PM" },
    { name: "Computer Science", code: "CS404", instructor: "Prof. Emma Brown", schedule: "Mon & Thu, 3:00-4:30 PM" },
    { name: "Chemistry", code: "CHEM505", instructor: "Dr. Nancy Green", schedule: "Wed & Fri, 10:00-11:30 AM" },
    { name: "Biology", code: "BIO606", instructor: "Dr. Steve Parker", schedule: "Tue & Thu, 1:00-2:30 PM" },
    { name: "English Literature", code: "ENG707", instructor: "Prof. Susan Clark", schedule: "Mon & Wed, 12:00-1:30 PM" },
    { name: "Economics", code: "ECON808", instructor: "Dr. Richard Wilson", schedule: "Fri, 9:30-11:00 AM" },
    { name: "Psychology", code: "PSY909", instructor: "Dr. Laura Collins", schedule: "Tue, 3:00-4:30 PM" },
  ];

  return (
    <Box className="coursesContent">
      <Typography variant="h5" sx={{ marginBottom: "20px", textAlign: "center", fontWeight: "bold" }}>
        Enrolled Courses
      </Typography>
      <Grid container spacing={3} justifyContent="center">
        {courses.map((course, index) => (
          <Grid item xs={12} sm={6} md={4} key={index}>
            <Card className="courseCard" variant="outlined">
              <CardContent>
                <Typography variant="h6" className="courseTitle">
                  {course.name}
                </Typography>
                <Typography variant="body2" className="courseCode">
                  Code: {course.code}
                </Typography>
                <Typography variant="body2" className="courseInstructor">
                  Instructor: {course.instructor}
                </Typography>
                <Typography variant="body2" className="courseSchedule">
                  Schedule: {course.schedule}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};

export default CoursesTab;
